#!/usr/bin/env python3
"""
Fetch USGS streamflow data and determine flood days for Michigan stations.
Flooding is determined when streamflow exceeds the flood stage threshold.
"""

import requests
import csv
import os
from datetime import datetime

# Read station IDs
with open('/root/data/michigan_stations.txt', 'r') as f:
    stations = [line.strip() for line in f if line.strip()]

print(f"Found {len(stations)} stations to check")

# Date range: April 1-7, 2025
start_date = "2025-04-01"
end_date = "2025-04-07"

# USGS Water Services API
# We'll fetch daily values and flood stage information

def get_flood_stage(station_id):
    """Get flood stage threshold for a station from USGS."""
    # Try to get flood stage from the NWIS flood stage service
    url = f"https://waterservices.usgs.gov/nwis/iv/?format=json&sites={station_id}&parameterCd=00065&siteStatus=all"
    try:
        response = requests.get(url, timeout=30)
        if response.status_code == 200:
            data = response.json()
            # Check if there's flood stage info in the response
            if 'value' in data and 'timeSeries' in data['value']:
                for ts in data['value']['timeSeries']:
                    if 'variable' in ts:
                        var = ts['variable']
                        # Flood stage might be in variable info or we need to check elsewhere
    except Exception as e:
        pass
    return None

def get_daily_streamflow(station_id, start, end):
    """Get daily streamflow values for a station."""
    # Parameter code 00060 = Discharge (cubic feet per second)
    # Parameter code 00065 = Gage height (feet)
    url = f"https://waterservices.usgs.gov/nwis/dv/?format=json&sites={station_id}&startDT={start}&endDT={end}&parameterCd=00060,00065&siteStatus=all"

    try:
        response = requests.get(url, timeout=30)
        if response.status_code == 200:
            return response.json()
    except Exception as e:
        print(f"Error fetching data for {station_id}: {e}")
    return None

def get_flood_thresholds(station_id):
    """
    Get flood stage/action stage thresholds from USGS flood service.
    Uses the AHPS (Advanced Hydrologic Prediction Service) data when available.
    """
    # Try the USGS Water Watch flood stage endpoint
    url = f"https://waterwatch.usgs.gov/webservices/floodstage?format=json&site={station_id}"
    try:
        response = requests.get(url, timeout=30)
        if response.status_code == 200:
            data = response.json()
            if 'sites' in data and len(data['sites']) > 0:
                site = data['sites'][0]
                return {
                    'action_stage': float(site.get('action_stage', 0)) if site.get('action_stage') else None,
                    'flood_stage': float(site.get('flood_stage', 0)) if site.get('flood_stage') else None,
                    'moderate_flood_stage': float(site.get('moderate_flood_stage', 0)) if site.get('moderate_flood_stage') else None,
                    'major_flood_stage': float(site.get('major_flood_stage', 0)) if site.get('major_flood_stage') else None
                }
    except Exception as e:
        pass
    return None

def check_flooding_via_percentile(station_id, start, end):
    """
    Alternative: Check if streamflow exceeds historical percentiles (e.g., 90th percentile).
    This is useful when explicit flood stages aren't available.
    """
    # Get statistics for the site
    stats_url = f"https://waterservices.usgs.gov/nwis/stat/?format=json&sites={station_id}&statReportType=daily&statTypeCd=p90"
    try:
        response = requests.get(stats_url, timeout=30)
        if response.status_code == 200:
            return response.json()
    except:
        pass
    return None

def get_instantaneous_values(station_id, start, end):
    """Get instantaneous values (more detailed) for gage height."""
    url = f"https://waterservices.usgs.gov/nwis/iv/?format=json&sites={station_id}&startDT={start}&endDT={end}&parameterCd=00065&siteStatus=all"
    try:
        response = requests.get(url, timeout=30)
        if response.status_code == 200:
            return response.json()
    except Exception as e:
        pass
    return None

# Main processing
results = []

for i, station_id in enumerate(stations):
    print(f"Processing station {i+1}/{len(stations)}: {station_id}")

    flood_days = 0

    # Get flood stage thresholds
    thresholds = get_flood_thresholds(station_id)

    if thresholds and thresholds.get('flood_stage'):
        flood_stage = thresholds['flood_stage']
        print(f"  Flood stage: {flood_stage} ft")

        # Get daily gage height values
        data = get_daily_streamflow(station_id, start_date, end_date)

        if data and 'value' in data and 'timeSeries' in data['value']:
            for ts in data['value']['timeSeries']:
                # Look for gage height (00065)
                if ts.get('variable', {}).get('variableCode', [{}])[0].get('value') == '00065':
                    values = ts.get('values', [{}])[0].get('value', [])
                    for v in values:
                        try:
                            gage_height = float(v['value'])
                            if gage_height >= flood_stage:
                                flood_days += 1
                                date_str = v.get('dateTime', 'unknown')[:10]
                                print(f"    Flooding on {date_str}: {gage_height} ft >= {flood_stage} ft")
                        except (ValueError, TypeError):
                            continue
    else:
        # Try using instantaneous values and check against any available threshold
        # Or use action stage if flood stage isn't available
        if thresholds and thresholds.get('action_stage'):
            action_stage = thresholds['action_stage']
            print(f"  No flood stage, using action stage: {action_stage} ft")

            data = get_daily_streamflow(station_id, start_date, end_date)

            if data and 'value' in data and 'timeSeries' in data['value']:
                for ts in data['value']['timeSeries']:
                    if ts.get('variable', {}).get('variableCode', [{}])[0].get('value') == '00065':
                        values = ts.get('values', [{}])[0].get('value', [])
                        for v in values:
                            try:
                                gage_height = float(v['value'])
                                # Using action stage as flood indicator
                                if gage_height >= action_stage:
                                    flood_days += 1
                                    date_str = v.get('dateTime', 'unknown')[:10]
                                    print(f"    Above action stage on {date_str}: {gage_height} ft >= {action_stage} ft")
                            except (ValueError, TypeError):
                                continue
        else:
            print(f"  No flood/action stage threshold available")

    if flood_days > 0:
        results.append({'station_id': station_id, 'flood_days': flood_days})
        print(f"  Total flood days: {flood_days}")

# Create output directory
os.makedirs('/root/output', exist_ok=True)

# Write results to CSV
output_file = '/root/output/flood_results.csv'
with open(output_file, 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['station_id', 'flood_days'])
    writer.writeheader()
    for result in results:
        writer.writerow(result)

print(f"\nResults written to {output_file}")
print(f"Found {len(results)} stations with at least one flood day")
